/**
 * Port of `whoosh.analysis.analyzers`.
 *
 * An analyzer is just a tokenizer followed by zero or more filters, wired into
 * one lazy generator chain. In Whoosh these are built with the `|` operator
 * (`RegexTokenizer() | LowercaseFilter() | StopFilter()`), which produces a
 * `CompositeAnalyzer`; here the composition is explicit.
 *
 * CANONICAL ENTRY POINT: `analyzer.analyze(value, opts)` -> Iterable<Token>.
 * `analyzer.call(value, opts)` is an alias with identical behaviour, provided
 * because Whoosh's analyzers are callable objects and the alias keeps ported call
 * sites readable.
 *
 * Note that `StandardAnalyzer` and friends are FUNCTIONS, not classes, in Whoosh
 * too - they are composition helpers that return a `CompositeAnalyzer`.
 */

import { Token } from './token.mjs';
import { STOP_WORDS } from './stopwords.mjs';
import {
  DEFAULT_WORD_PATTERN,
  IDTokenizer,
  RegexTokenizer,
  SpaceSeparatedTokenizer,
} from './tokenizers.mjs';
import { LowercaseFilter, StopFilter } from './filters.mjs';

/**
 * Base class for analyzers (Whoosh's `Analyzer`, a `Composable`).
 *
 * The base analyzes to nothing; concrete analyzers override `analyze()`.
 */
export class Analyzer {
  /**
   * @param {unknown} _value the field value to analyze
   * @param {object} [_opts] pipeline options: `{positions, chars, start_pos,
   *   start_char, mode, removestops, keeporiginal, tokenize}`
   * @returns {Generator<Token>}
   */
  // eslint-disable-next-line no-unused-vars
  *analyze(_value, _opts = {}) {
    // Abstract: no pipeline configured.
  }

  /**
   * Alias for {@link Analyzer#analyze} (Whoosh analyzers are callable).
   * @param {unknown} value
   * @param {object} [opts]
   * @returns {Iterable<Token>}
   */
  call(value, opts = {}) {
    return this.analyze(value, opts);
  }

  /** Whoosh's `Composable.clean()` hook. */
  clean() {}

  /** Whoosh's `has_morph()`: true if any stage does stemming/morphology. */
  has_morph() {
    return false;
  }
}

/**
 * Port of `whoosh.analysis.analyzers.CompositeAnalyzer`.
 *
 * Holds a tokenizer followed by filters and chains them lazily. As in Whoosh, a
 * nested CompositeAnalyzer is FLATTENED into this one's item list, so
 * `CompositeAnalyzer(StandardAnalyzer(), someFilter)` behaves as a single chain.
 */
export class CompositeAnalyzer extends Analyzer {
  /**
   * @param {...(object)} composables a tokenizer first, then filters (or another
   *   CompositeAnalyzer, whose items get spliced in)
   */
  constructor(...composables) {
    super();
    /** @type {object[]} pipeline stages, in order */
    this.items = [];
    for (const comp of composables) {
      if (!comp) continue;
      if (comp instanceof CompositeAnalyzer && Array.isArray(comp.items)) {
        this.items.push(...comp.items);
      } else {
        this.items.push(comp);
      }
    }
  }

  /**
   * Run the chain. Returns a lazy iterable: the tokenizer is not even started
   * until the caller pulls the first token.
   * @param {unknown} value
   * @param {object} [opts] forwarded to the tokenizer and to every filter
   * @returns {Iterable<Token>}
   */
  analyze(value, opts = {}) {
    const items = this.items;
    if (!items.length) return [];

    const head = items[0];
    let gen;
    if (typeof head.tokenize === 'function') {
      gen = head.tokenize(value, opts);
    } else if (typeof head.analyze === 'function') {
      // Tolerate an analyzer used as the head of the chain.
      gen = head.analyze(value, opts);
    } else {
      return [];
    }

    for (let i = 1; i < items.length; i += 1) {
      const item = items[i];
      if (item && typeof item.filter === 'function') {
        gen = item.filter(gen, opts);
      }
    }
    return gen;
  }

  /** Reset every stage (Whoosh's `CompositeAnalyzer.clean`). */
  clean() {
    for (const item of this.items) {
      if (item && typeof item.clean === 'function') item.clean();
    }
  }

  /** True if any stage performs morphology (stemming). */
  has_morph() {
    return this.items.some((item) => item && typeof item.has_morph === 'function' && item.has_morph());
  }
}

/**
 * Port of `whoosh.analysis.analyzers.StandardAnalyzer` - the default analyzer of
 * the `TEXT` field type.
 *
 * Chain, in order:
 *   RegexTokenizer(DEFAULT_WORD_PATTERN, gaps=false)
 *     -> LowercaseFilter()
 *     -> StopFilter({stoplist: STOP_WORDS, minsize: 2, maxsize: null})
 *
 * There is NO stemming here (that is `StemmingAnalyzer`). Passing
 * `stoplist: null` drops the StopFilter stage ENTIRELY rather than using an empty
 * stop list, because an empty stop list would still apply `minsize`.
 *
 * @param {object} [opts]
 * @param {RegExp|string} [opts.expression] token pattern
 * @param {Iterable<string>|null} [opts.stoplist] null => no StopFilter at all
 * @param {number} [opts.minsize] default 2
 * @param {number|null} [opts.maxsize] default null (no upper bound)
 * @param {boolean} [opts.gaps] treat the expression as separators
 * @returns {CompositeAnalyzer}
 */
export function StandardAnalyzer(opts = {}) {
  const {
    expression = DEFAULT_WORD_PATTERN,
    stoplist = STOP_WORDS,
    minsize = 2,
    maxsize = null,
    gaps = false,
  } = opts || {};

  const stages = [new RegexTokenizer(expression, gaps), new LowercaseFilter()];
  if (stoplist !== null && stoplist !== undefined) {
    stages.push(new StopFilter({ stoplist, minsize, maxsize }));
  }
  return new CompositeAnalyzer(...stages);
}

/**
 * Port of `whoosh.analysis.analyzers.SimpleAnalyzer`:
 * RegexTokenizer -> LowercaseFilter. No stop words, no minimum size, so single
 * characters survive.
 *
 * @param {object} [opts]
 * @param {RegExp|string} [opts.expression]
 * @param {boolean} [opts.gaps]
 * @returns {CompositeAnalyzer}
 */
export function SimpleAnalyzer(opts = {}) {
  const { expression = DEFAULT_WORD_PATTERN, gaps = false } = opts || {};
  return new CompositeAnalyzer(new RegexTokenizer(expression, gaps), new LowercaseFilter());
}

/**
 * Port of `whoosh.analysis.analyzers.IDAnalyzer` - the default analyzer of the
 * `ID` field type.
 *
 * Just an IDTokenizer: the whole value becomes one verbatim term, so an ID field
 * is findable only by its exact full string. `lowercase: true` appends a
 * LowercaseFilter (mirror that on the query side if you use it), which is the
 * only way to get case-insensitive IDs.
 *
 * @param {object} [opts]
 * @param {boolean} [opts.lowercase] append a LowercaseFilter
 * @returns {CompositeAnalyzer}
 */
export function IDAnalyzer(opts = {}) {
  const { lowercase = false } = opts || {};
  const stages = [new IDTokenizer()];
  if (lowercase) stages.push(new LowercaseFilter());
  return new CompositeAnalyzer(...stages);
}

/**
 * Port of `whoosh.analysis.analyzers.KeywordAnalyzer` - the default analyzer of
 * the `KEYWORD` field type.
 *
 * Splits on spaces/tabs/CR/LF only (or on commas when `commas: true`, with the
 * pieces trimmed), and by default does NOT lowercase and does NOT remove stop
 * words.
 *
 * @param {object} [opts]
 * @param {boolean} [opts.lowercase] append a LowercaseFilter
 * @param {boolean} [opts.commas] split on ',' instead of whitespace
 * @returns {CompositeAnalyzer}
 */
export function KeywordAnalyzer(opts = {}) {
  const { lowercase = false, commas = false } = opts || {};
  // Whoosh: CommaSeparatedTokenizer is RegexTokenizer(r"[^,]+") | StripFilter().
  // We fold the strip into the pattern so no extra filter class is needed.
  const tokenizer = commas
    ? new RegexTokenizer(/[^,\s](?:[^,]*[^,\s])?/, false)
    : new SpaceSeparatedTokenizer();
  const stages = [tokenizer];
  if (lowercase) stages.push(new LowercaseFilter());
  return new CompositeAnalyzer(...stages);
}

